<script>
  function switchStakeholderTab(target) {
    const academicPanel = document.getElementById('tab-panel-academic');
    const sisPanel = document.getElementById('tab-panel-sis');
    const academicBtn = document.getElementById('tab-btn-academic');
    const sisBtn = document.getElementById('tab-btn-sis');

    if (!academicPanel || !sisPanel || !academicBtn || !sisBtn) return;

    if (target === 'academic') {
      academicPanel.classList.remove('hidden');
      academicPanel.classList.add('grid');
      sisPanel.classList.add('hidden');
      sisPanel.classList.remove('grid');

      // Styles for active academic
      academicBtn.className = 'px-5 py-2 rounded-DEFAULT bg-primary-container text-on-primary font-title-sm text-title-sm shadow-sm transition-all flex items-center gap-2';
      sisBtn.className = 'px-5 py-2 rounded-DEFAULT bg-transparent text-on-surface-variant hover:text-on-surface font-title-sm text-title-sm transition-all flex items-center gap-2';
    } else {
      sisPanel.classList.remove('hidden');
      sisPanel.classList.add('grid');
      academicPanel.classList.add('hidden');
      academicPanel.classList.remove('grid');

      // Styles for active sis
      sisBtn.className = 'px-5 py-2 rounded-DEFAULT bg-primary-container text-on-primary font-title-sm text-title-sm shadow-sm transition-all flex items-center gap-2';
      academicBtn.className = 'px-5 py-2 rounded-DEFAULT bg-transparent text-on-surface-variant hover:text-on-surface font-title-sm text-title-sm transition-all flex items-center gap-2';
    }
  }
